  // Draw any image (data URI / URL) into a small square PNG so it is cheap to sync.
  function rasterize(src, size) {
    return new Promise((resolve) => {
      const img = new Image();
      img.crossOrigin = 'anonymous';
      img.onload = () => {
        const c = document.createElement('canvas');
        c.width = c.height = size;
        const ctx = c.getContext('2d');
        const w = img.naturalWidth || size;
        const h = img.naturalHeight || size;
        const s = Math.min(size / w, size / h);
        ctx.imageSmoothingEnabled = true;
        ctx.imageSmoothingQuality = 'high';
        ctx.drawImage(img, (size - w * s) / 2, (size - h * s) / 2, w * s, h * s);
        try {
          resolve(c.toDataURL('image/png'));
        } catch (e) {
          resolve(cleanIcon(src)); // tainted canvas: fall back to the raw URL
        }
      };
      img.onerror = () => resolve('');
      img.src = src;
    });
  }

  // Minimal MD5 (needed for GameJolt API signatures).
  function md5(str) {
    const bytes = new TextEncoder().encode(str);
    const len = bytes.length;
    const nBlocks = ((len + 8) >> 6) + 1;
    const words = new Uint32Array(nBlocks * 16);
    for (let i = 0; i < len; i++) words[i >> 2] |= bytes[i] << ((i % 4) * 8);
    words[len >> 2] |= 0x80 << ((len % 4) * 8);
    words[nBlocks * 16 - 2] = (len * 8) >>> 0;
    words[nBlocks * 16 - 1] = Math.floor(len / 0x20000000);
    const K = new Uint32Array(64);
    for (let i = 0; i < 64; i++) K[i] = Math.floor(Math.abs(Math.sin(i + 1)) * 0x100000000);
    const R = [7, 12, 17, 22, 5, 9, 14, 20, 4, 11, 16, 23, 6, 10, 15, 21];
    let a0 = 0x67452301, b0 = 0xefcdab89, c0 = 0x98badcfe, d0 = 0x10325476;
    for (let blk = 0; blk < words.length; blk += 16) {
      let A = a0, B = b0, C = c0, D = d0;
      for (let i = 0; i < 64; i++) {
        let F, g;
        if (i < 16) { F = (B & C) | (~B & D); g = i; }
        else if (i < 32) { F = (D & B) | (~D & C); g = (5 * i + 1) % 16; }
        else if (i < 48) { F = B ^ C ^ D; g = (3 * i + 5) % 16; }
        else { F = C ^ (B | ~D); g = (7 * i) % 16; }
        const s = R[(i >> 4) * 4 + (i % 4)];
        F = (F + A + K[i] + words[blk + g]) >>> 0;
        A = D; D = C; C = B;
        B = (B + ((F << s) | (F >>> (32 - s)))) >>> 0;
      }
      a0 = (a0 + A) >>> 0; b0 = (b0 + B) >>> 0; c0 = (c0 + C) >>> 0; d0 = (d0 + D) >>> 0;
    }
    return [a0, b0, c0, d0].map((w) => {
      let s = '';
      for (let j = 0; j < 4; j++) s += ((w >>> (j * 8)) & 255).toString(16).padStart(2, '0');
      return s;
    }).join('');
  }

  async function gjRequest(endpoint, params, privateKey) {
    const qs = Object.keys(params).map((k) => `${k}=${encodeURIComponent(params[k])}`).join('&');
    let url = `https://api.gamejolt.com/api/game/v1_2/${endpoint}/?${qs}&format=json`;
    url += '&signature=' + md5(url + privateKey);
    const res = await fetch(url);
    const json = await res.json();
    return json && json.response;
  }

