    // ------------------------------------------------------------------
    // Iframe / External Window Bridge
    // ------------------------------------------------------------------
    handleExternalMessage(event) {
      const data = event.data;
      if (!data || data.source !== 'GEOMETRY_RUSH_PARTY_UI') return;
      switch (data.action) {
        case 'PARTY_CREATED':
        case 'PARTY_JOINED':
          if (data.payload && data.payload.code) this.code = data.payload.code;
          this.fire('whenClientJoined');
          this.fire('whenJoinedParty');
          break;
        case 'PARTY_LEFT':
          this.fire('whenClientLeft');
          this.fire('whenLeftParty');
          break;
        case 'PLAYER_JOINED':
          this.lastJoined = cleanName(data.payload && data.payload.name);
          this.fire('whenPlayerJoined');
          break;
        case 'PLAYER_LEFT':
          this.lastLeft = cleanName(data.payload && data.payload.name);
          this.fire('whenPlayerLeft');
          break;
        case 'PLAYER_KICKED':
          this.lastKicked = cleanName(data.payload && data.payload.name);
          this.fire('whenPlayerKicked');
          break;
        case 'CHAT_MESSAGE':
          this.lastChatSender = cleanName(data.payload && data.payload.sender);
          this.lastChatMessage = String((data.payload && data.payload.text) || '');
          this.fire('whenMessageReceived');
          break;
        case 'EXIT':
          this.closeMenu(true);
          break;
      }
    }

    notifyIframe(type, payload) {
      const iframes = document.querySelectorAll('iframe');
      for (const iframe of iframes) {
        try {
          if (iframe.contentWindow) {
            iframe.contentWindow.postMessage(Object.assign({ source: 'GEOMETRY_RUSH_PARTY_EXT', type }, payload), '*');
          }
        } catch(e){}
      }
    }

    // ------------------------------------------------------------------
    // Block implementations
    // ------------------------------------------------------------------
    async login(args) {
      const name = cleanName(args.USERNAME);
      const token = Scratch.Cast.toString(args.TOKEN).trim();
      if (!name) {
        this.loggedIn = false;
        this.lastError = 'ENTER A GAMEJOLT USERNAME.';
        this.render();
        return;
      }
      if (this.inParty() && !sameName(name, this.username)) this.leaveParty();
      this.username = name;
      this.token = token;
      this.gjAvatar = '';
      this.verified = false;

      if (this.gjGameId && this.gjKey) {
        try {
          const auth = await gjRequest('users/auth',
            { game_id: this.gjGameId, username: name, user_token: token }, this.gjKey);
          if (!auth || String(auth.success) !== 'true') {
            this.loggedIn = false;
            this.lastError = 'GAMEJOLT LOGIN FAILED. CHECK USERNAME AND TOKEN.';
            this.render();
            return;
          }
          this.verified = true;
          try {
            const u = await gjRequest('users', { game_id: this.gjGameId, username: name }, this.gjKey);
            const user = u && u.users && u.users[0];
            if (user && user.avatar_url) this.gjAvatar = cleanIcon(user.avatar_url);
          } catch (e) { /* avatar is optional */ }
        } catch (e) {
          this.loggedIn = false;
          this.lastError = 'COULD NOT REACH GAMEJOLT.';
          this.render();
          return;
        }
      }

      this.loggedIn = true;
      this.lastError = '';
      this.uiError = '';
      this.render();
      this.notifyIframe('LOGIN', { username: this.username, token: this.token });
    }

    setGameJoltKeys(args) {
      this.gjGameId = Scratch.Cast.toString(args.ID).trim();
      this.gjKey = Scratch.Cast.toString(args.KEY).trim();
    }

    logout() {
      if (this.inParty()) this.leaveParty();
      this.loggedIn = false;
      this.verified = false;
      this.username = '';
      this.token = '';
      this.gjAvatar = '';
      this.render();
    }

